    # Try to find two lines that cover all points
    for i in range(n):
        for j in range(i + 1, n):
            line_points = [targets[i], targets[j]]
            for k in range(n):
                if k != i and k != j and is_collinear(line_points[0], line_points[1], targets[k]):
                    line_points.append(targets[k])
            if len(line_points) == n:
                return "success"

    return "failure"

